#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, renameSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';
import { ROOT, sourceDigest, evaluationDigest } from './evidence.mjs';
import { CONFIG } from './config.mjs';

export const MENU_VISIT_MS = CONFIG.native.longJourney.menuVisitSeconds * 1000;
export const REQUIRED_NATIVE_CHECKS = [
  'native-overlay', 'preload-isolation', 'painted-canvas', 'save-reload', 'menu-singleton',
  'menu-codex', 'menu-battle', 'hero-choice-reset-preserve',
  'v07-codex-strict-legacy', 'v07-codex-legacy-ack-normalization', 'v07-codex-unacquired-goal',
  'v07-codex-offer-stays-silhouette', 'v07-codex-selection-reveals-one', 'v07-codex-acquired-ack-only',
  'v07-codex-restart-preservation', 'v07-codex-first-kill-reveals', 'v07-codex-owned-without-kill-masked',
  'v07-level-over-10-save-reload', 'v07-level-over-10-network-roundtrip',
  'v07-pvp-party-in-every-row', 'v07-pvp-selected-id',
  'v07-pvp-keyboard-navigation', 'v07-pvp-focus-retained', 'v07-pvp-removed-row-focus-fallback',
  'v07-pvp-preview-id-roundtrip', 'v07-companion-reincarnation-confirm',
  'v07-companion-reincarnation-cancel', 'v07-companion-reincarnation-target-change-invalidates',
  'v07-rare-third-choice-ui',
];
export function parseRunArguments(args) {
  const [output, minutes = '5', profile = 'active', ...extra] = args;
  if (!output || extra.length || !CONFIG.native.durationsMinutes.map(String).includes(minutes) ||
    !CONFIG.native.profiles.includes(profile) || (Number(minutes) === CONFIG.native.longJourney.minutes && profile !== CONFIG.native.longJourney.profile)) {
    throw new Error('Usage: node .harness/v7/loop/e2e.mjs <output.json> [0|5|15|30|180 minutes] [active|idle|intermittent]\n0 = diagnostics; 5/15/30 = observation; 180 active = continuous play with menu visits every 10 minutes.');
  }
  return { output, minutes, profile };
}
export const menuVisitSchedule = minutes => minutes === CONFIG.native.longJourney.minutes
  ? Array.from({ length: minutes * 60_000 / MENU_VISIT_MS }, (_, index) => (index + 1) * MENU_VISIT_MS) : [];

/** Sample before consuming a ready offer; later reincarnations cannot replace the first observation. */
export function recordFirstReadiness(observation, ready, elapsedMs) {
  if (ready && observation.firstReadyElapsedMs === null) observation.firstReadyElapsedMs = elapsedMs;
}

/** A crash leaves the last whole checkpoint, never a truncated original JSON. */
export function writeRunCheckpoint(file, report) {
  const temporary = `${file}.checkpoint.tmp`;
  writeFileSync(temporary, `${JSON.stringify(report, null, 2)}\n`);
  renameSync(temporary, file);
}

async function main() {
const { output, minutes, profile } = parseRunArguments(process.argv.slice(2));
const file = resolve(output);
if (existsSync(file)) throw new Error('Output already exists; preserve the original and choose a new path.');
mkdirSync(dirname(file), { recursive: true });
const digest = sourceDigest();
const toolsDigest = evaluationDigest();
const run = (cmd, args, env, timeout) => new Promise((accept, reject) => {
  const child = spawn(cmd, args, { cwd: ROOT, env, stdio: 'inherit' });
  const timer = setTimeout(() => child.kill('SIGTERM'), timeout);
  child.on('error', (error) => { clearTimeout(timer); reject(error); });
  child.on('exit', (code, signal) => {
    clearTimeout(timer);
    code === 0 ? accept() : reject(new Error(`${cmd} exited ${code ?? signal}`));
  });
});
try {
  await run('npm', ['run', 'build'], process.env, 120_000);
  if (sourceDigest() !== digest) throw new Error('Source changed during build; rerun.');
  const env = { ...process.env, SMOKE: '1', DESMON_SERVER_URL: '', DESMON_E2E_DIGEST: digest, DESMON_E2E_TOOLS: toolsDigest };
  delete env.ELECTRON_RUN_AS_NODE;
  await run(process.execPath, [resolve(ROOT, 'node_modules/electron/cli.js'),
    resolve(ROOT, '.harness/v7/loop/electron-e2e.cjs'), file, minutes, profile], env,
  Number(minutes) * 60_000 + 120_000);
  if (sourceDigest() !== digest || evaluationDigest() !== toolsDigest) throw new Error('Source/tools changed during E2E; evidence is stale.');
} catch (error) {
  // Keep native failure evidence when it exists; a launcher failure remains visible separately.
  writeFileSync(`${file}.failure.txt`, `${error.stack ?? error}\n`);
  console.error(error.message);
  process.exitCode = 1;
}
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try { await main(); } catch (error) { console.error(error.message); process.exitCode = 1; }
}

// Tray + context menu (SPEC F23, Assumption 16). Electron-free by injection
// (persistence.ts pattern): Tray/Menu construction is passed in by
// src/main/index.ts, so the menu contents and the rebuild-on-mode-change
// behavior have real vitest coverage without an Electron process.

import type { InputModePayload } from '../shared/ipc.js';
import { GAME_SCALES, SCALE_LABELS } from './settings.js';

/** First (disabled) menu row; tests pin the version against package.json. */
export const TRAY_TITLE = 'DesMon v0.6.0';
export const TRAY_TOOLTIP = 'DesMon';
export const INPUT_GLOBAL_LABEL = 'Input: Global';
export const INPUT_FALLBACK_LABEL = 'Input: Window-only (grant Accessibility…)';
export const COLLECTION_LABEL = 'Collection & Battle…';
export const SETTINGS_LABEL = 'Setting';
export const RESET_LABEL = 'Reset Progress';
export const QUIT_LABEL = 'Quit';

/** Structural subset of Electron.MenuItemConstructorOptions this emits. */
export interface TrayMenuItem {
  label?: string;
  type?: 'separator' | 'radio';
  checked?: boolean;
  submenu?: TrayMenuItem[];
  enabled?: boolean;
  click?: () => void;
}

export interface TrayMenuActions {
  /** Fallback status row clicked → Accessibility pane deep link. */
  openAccessibilitySettings: () => void;
  /** "Collection & Battle…" clicked → open the menu window (SPEC F52). */
  openCollection: () => void;
  /** "Reset Progress" clicked → send desmon:reset to the renderer. */
  resetProgress: () => void;
  /** "Quit" clicked → app.quit(). */
  quit: () => void;
  setGameScale: (scale: number) => void;
}

/**
 * Pure menu description for an input mode. In global mode the status row is
 * informational (disabled); in fallback mode clicking it opens the macOS
 * Accessibility settings pane so the user can grant the permission.
 */
export function buildTrayMenuTemplate(
  mode: InputModePayload,
  actions: TrayMenuActions,
  gameScale = 1,
  title = TRAY_TITLE,
): TrayMenuItem[] {
  const status: TrayMenuItem =
    mode.mode === 'global'
      ? { label: INPUT_GLOBAL_LABEL, enabled: false }
      : { label: INPUT_FALLBACK_LABEL, click: actions.openAccessibilitySettings };
  return [
    { label: title, enabled: false },
    status,
    { type: 'separator' },
    { label: COLLECTION_LABEL, click: actions.openCollection },
    {
      label: SETTINGS_LABEL,
      submenu: [
        { label: 'Game size', enabled: false },
        ...GAME_SCALES.map((scale, i): TrayMenuItem => ({
          label: SCALE_LABELS[i],
          type: 'radio',
          checked: scale === gameScale,
          click: () => actions.setGameScale(scale),
        })),
        { type: 'separator' },
        { label: title, enabled: false },
      ],
    },
    { label: RESET_LABEL, click: actions.resetProgress },
    { label: QUIT_LABEL, click: actions.quit },
  ];
}

/** The subset of Electron.Tray this module drives. */
export interface TrayLike {
  setToolTip(tip: string): void;
  setContextMenu(menu: unknown): void;
}

export interface TrayDeps {
  getGameScale?: () => number;
  title?: string;
  /** Wraps `new Tray(nativeImage.createFromBuffer(encodeTrayIconPng()))`. */
  createTray: () => TrayLike;
  /** Wraps `Menu.buildFromTemplate(template)`. */
  buildMenu: (template: TrayMenuItem[]) => unknown;
  /** Initial input mode — main wires getCurrentInputMode (T04). */
  getInputMode: () => InputModePayload;
  actions: TrayMenuActions;
}

export interface TrayController {
  /** Rebuild the context menu for a new input mode (T04 mode events). */
  refresh(mode: InputModePayload): void;
}

// Module-scope reference (Assumption 16): without a live reference the Tray
// would be garbage-collected and the menu-bar icon silently vanish.
let activeTray: TrayLike | null = null;

/** The currently live tray, if any (module-scope keep-alive; used by tests). */
export function getActiveTray(): TrayLike | null {
  return activeTray;
}

/** Create the tray, apply tooltip + initial menu, return the rebuild handle. */
export function setupTray(deps: TrayDeps): TrayController {
  const tray = deps.createTray();
  activeTray = tray;
  tray.setToolTip(TRAY_TOOLTIP);
  const refresh = (mode: InputModePayload): void => {
    tray.setContextMenu(deps.buildMenu(buildTrayMenuTemplate(mode, deps.actions, deps.getGameScale?.() ?? 1, deps.title)));
  };
  refresh(deps.getInputMode());
  return { refresh };
}

// T17 — tray icon + menu (SPEC F23, Assumption 16).
//
// trayIcon.ts and tray.ts are electron-free with injected dependencies, so:
// - the PNG encoder is verified by DECODING its output: an independent
//   (table-free) CRC-32 implementation checks every chunk checksum, and
//   node:zlib inflateSync recovers the scanlines, which must reproduce the
//   pixel matrix exactly;
// - the menu template and the rebuild-on-mode-change behavior run against
//   fake Tray/Menu factories;
// - the live Electron wiring in src/main/index.ts is pinned as source text
//   (same approach as the window/smoke source-contract tests), and so is
//   src/main/menuWindow.ts (T46/F52), which the tray item is the only opener of.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { inflateSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import type { InputModePayload } from '../src/shared/ipc.js';
import {
  buildTrayMenuTemplate,
  COLLECTION_LABEL,
  getActiveTray,
  INPUT_FALLBACK_LABEL,
  INPUT_GLOBAL_LABEL,
  QUIT_LABEL,
  RESET_LABEL,
  SETTINGS_LABEL,
  setupTray,
  TRAY_TITLE,
  TRAY_TOOLTIP,
} from '../src/main/tray.js';
import type { TrayLike, TrayMenuActions, TrayMenuItem } from '../src/main/tray.js';
import {
  crc32,
  encodeTrayIconPng,
  TRAY_ICON_PALETTE,
  TRAY_ICON_PIXELS,
  TRAY_ICON_SIZE,
} from '../src/main/trayIcon.js';

const GLOBAL_MODE: InputModePayload = { mode: 'global', accessibilityGranted: true };
const FALLBACK_MODE: InputModePayload = { mode: 'fallback', accessibilityGranted: false };

/** Independent CRC-32 (bitwise, no lookup table) to cross-check the encoder's. */
function referenceCrc32(bytes: Uint8Array): number {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let k = 0; k < 8; k++) {
      crc = (crc & 1) === 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1;
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

interface ParsedChunk {
  type: string;
  data: Buffer;
  crc: number;
  crcInput: Buffer;
}

function parseChunks(png: Buffer): ParsedChunk[] {
  const chunks: ParsedChunk[] = [];
  let offset = 8; // skip the signature
  while (offset < png.length) {
    const length = png.readUInt32BE(offset);
    chunks.push({
      type: png.subarray(offset + 4, offset + 8).toString('latin1'),
      data: png.subarray(offset + 8, offset + 8 + length),
      crc: png.readUInt32BE(offset + 8 + length),
      crcInput: png.subarray(offset + 4, offset + 8 + length),
    });
    offset += 12 + length;
  }
  return chunks;
}

function chunkOfType(png: Buffer, type: string): ParsedChunk {
  const found = parseChunks(png).find((chunk) => chunk.type === type);
  if (found === undefined) {
    throw new Error(`no ${type} chunk`);
  }
  return found;
}

function noopActions(): TrayMenuActions {
  return {
    openAccessibilitySettings: () => {},
    openCollection: () => {},
    resetProgress: () => {},
    quit: () => {},
    setGameScale: () => {},
  };
}

describe('tray icon pixel matrix (F23: sprites-as-code, no asset file)', () => {
  it('is a 16×16 matrix whose every char is in the palette', () => {
    expect(TRAY_ICON_PIXELS).toHaveLength(TRAY_ICON_SIZE);
    for (const row of TRAY_ICON_PIXELS) {
      expect(row).toHaveLength(TRAY_ICON_SIZE);
      for (const char of row) {
        expect(TRAY_ICON_PALETTE[char]).toBeDefined();
      }
    }
  });

  it('uses at least one transparent and one opaque pixel', () => {
    const flat = TRAY_ICON_PIXELS.join('');
    expect(flat).toContain('.');
    expect(flat).toMatch(/[^.]/);
  });
});

describe('pure-code PNG encoder (trayIcon.ts)', () => {
  const png = encodeTrayIconPng();

  it('starts with the PNG signature and frames IHDR, IDAT, IEND in order', () => {
    expect([...png.subarray(0, 8)]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    expect(parseChunks(png).map((chunk) => chunk.type)).toEqual(['IHDR', 'IDAT', 'IEND']);
  });

  it('declares a 16×16, 8-bit, RGBA, non-interlaced image in IHDR', () => {
    const ihdr = chunkOfType(png, 'IHDR');
    expect(ihdr.data).toHaveLength(13);
    expect(ihdr.data.readUInt32BE(0)).toBe(TRAY_ICON_SIZE); // width
    expect(ihdr.data.readUInt32BE(4)).toBe(TRAY_ICON_SIZE); // height
    expect(ihdr.data[8]).toBe(8); // bit depth
    expect(ihdr.data[9]).toBe(6); // color type: truecolor + alpha
    expect(ihdr.data[10]).toBe(0); // compression: deflate
    expect(ihdr.data[11]).toBe(0); // filter method 0
    expect(ihdr.data[12]).toBe(0); // no interlace
  });

  it('writes a valid CRC-32 over type+data for every chunk', () => {
    for (const chunk of parseChunks(png)) {
      expect(chunk.crc).toBe(referenceCrc32(chunk.crcInput));
      expect(chunk.crc).toBe(crc32(chunk.crcInput)); // both implementations agree
    }
  });

  it('inflates IDAT to filter-0 scanlines that reproduce the matrix exactly', () => {
    const raw = inflateSync(chunkOfType(png, 'IDAT').data);
    const stride = 1 + TRAY_ICON_SIZE * 4;
    expect(raw).toHaveLength(TRAY_ICON_SIZE * stride);
    for (let y = 0; y < TRAY_ICON_SIZE; y++) {
      expect(raw[y * stride]).toBe(0); // filter type None
      for (let x = 0; x < TRAY_ICON_SIZE; x++) {
        const char = TRAY_ICON_PIXELS[y]?.[x] ?? '';
        const expected = TRAY_ICON_PALETTE[char] ?? [0, 0, 0, 0];
        const p = y * stride + 1 + x * 4;
        expect([raw[p], raw[p + 1], raw[p + 2], raw[p + 3]]).toEqual([...expected]);
      }
    }
  });

  it('encodes unknown palette chars as transparent instead of throwing', () => {
    const png2 = encodeTrayIconPng(['?a', 'b?'], { a: [1, 2, 3, 255], b: [4, 5, 6, 255] });
    const raw = inflateSync(chunkOfType(png2, 'IDAT').data);
    // Row 0: filter, then '?' (transparent) and 'a'.
    expect([raw[1], raw[2], raw[3], raw[4]]).toEqual([0, 0, 0, 0]);
    expect([raw[5], raw[6], raw[7], raw[8]]).toEqual([1, 2, 3, 255]);
  });
});

