// Exact progression formulas; the registered production parameters own the curves.
import { PROGRESSION_PARAMETERS as progression } from './progression.js';

/** +1 damage per hero level (visible stat). */
export const damageForLevel = (level: number): number => level;

/** Crit chance (rng-injected at the engine layer). */
export const CRIT_CHANCE = 0.1;

/** Crit damage multiplier. */
export const CRIT_MULT = 2;

/** Party sorting is frequent; each distinct curve owns a bounded 512-index cache. */
const hpCurve = (numerator: number, denominator: number, tailStartIndex: number | null = null,
  tailNumerator = numerator, tailDenominator = denominator): ((index: number) => bigint) => {
  const hpCache = new Map<number, bigint>();
  const n = BigInt(numerator), d = BigInt(denominator);
  const t = BigInt(tailNumerator), u = BigInt(tailDenominator);
  return (index) => {
    const normalized = Math.max(0, Math.floor(index));
    const cached = hpCache.get(normalized);
    if (cached !== undefined) return cached;
    const i = BigInt(normalized);
    const a = tailStartIndex === null ? i : BigInt(Math.min(normalized, tailStartIndex));
    const b = i - a;
    // Preserve fractional prefix HP until this single final division.
    const hp = (10n * n ** a * t ** b) / (d ** a * u ** b);
    if (hpCache.size >= 512) hpCache.clear();
    hpCache.set(normalized, hp);
    return hp;
  };
};

/** Legacy base HP also defines companion power; field experiments must not change it. */
export const monsterMaxHp = hpCurve(progression.companionHpNumerator, progression.companionHpDenominator);
/** Field-only HP; keep its curve and cache separate from owned companions/PvP. */
export const fieldMonsterMaxHp = hpCurve(progression.fieldHpNumerator, progression.fieldHpDenominator,
  progression.fieldHpTailStartIndex, progression.fieldHpTailNumerator, progression.fieldHpTailDenominator);

/** XP granted for killing the monster at `index`. */
export const xpReward = (index: number): number => progression.xpRewardBase + progression.xpRewardPerIndex * index;

/** XP needed to advance FROM `level` to the next: 20, 28, 39, 54 … */
export const xpToNext = (level: number): number =>
  Math.floor(progression.xpBase * Math.pow(progression.xpGrowth, level - 1));

// Gold purchases use one reducer so a queued click cannot spend twice.
import type { GameEvent, GameState } from './types.js';
import { copyProgress, discoveryContext, migrateProgress } from './progress.js';
import { RARE_MONSTERS, requirementsMet } from './discovery.js';
import { heroForm } from './hero.js';

export const TRAINING_MAX_LEVEL = 10;
export const LURE_CHARGES = 20;
export type EconomyAction = { type: 'shopBuy'; item: 'training' | 'lure'; shopSerial: number };

const bounded = (value: number, max: number): number =>
  Number.isFinite(value) ? Math.max(0, Math.min(max, Math.floor(value))) : 0;
export const trainingCost = (level: number): number => 75 * (bounded(level, TRAINING_MAX_LEVEL) + 1) ** 2;
export const lureCost = (reincarnations: number): number => 75 + 25 * bounded(reincarnations, 100);
export const trainedHeroPower = (base: bigint, trainingLevel = 0): bigint =>
  base * BigInt(100 + 5 * bounded(trainingLevel, TRAINING_MAX_LEVEL)) / 100n;

export function applyEconomyAction(state: Readonly<GameState>, action: EconomyAction):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const progress = state.progress ? copyProgress(state.progress) : migrateProgress(state, state.monster.speciesId);
  if (action.type !== 'shopBuy' || !Number.isSafeInteger(action.shopSerial) ||
    action.shopSerial !== progress.shopSerial || progress.shopSerial >= Number.MAX_SAFE_INTEGER - 1) {
    return { error: 'Stale shop purchase' };
  }
  if (action.item !== 'training' && action.item !== 'lure') return { error: 'Unknown shop item' };
  if (action.item === 'training' && progress.trainingLevel >= TRAINING_MAX_LEVEL) return { error: 'Training is complete' };
  if (action.item === 'lure' && progress.lureRemaining > 0) return { error: 'A lure is already active' };
  if (action.item === 'lure') {
    const context = discoveryContext({ ...state, progress }, state.hero ? heroForm(state.hero.equipped.formId)?.type : undefined);
    if (!RARE_MONSTERS.some((monster) => requirementsMet(monster.requirements, context))) {
      return { error: 'Meet a rare monster discovery condition before buying a lure' };
    }
  }
  const cost = action.item === 'training' ? trainingCost(progress.trainingLevel) : lureCost(state.hero?.reincarnations ?? 0);
  if (!Number.isSafeInteger(state.coins) || state.coins < cost) return { error: 'Not enough gold' };
  if (!Number.isSafeInteger(progress.goldSpent + cost)) return { error: 'Gold history limit reached' };
  if (action.item === 'training') progress.trainingLevel++;
  else progress.lureRemaining = LURE_CHARGES;
  progress.shopSerial++;
  progress.goldSpent += cost;
  return { state: { ...state, coins: state.coins - cost, progress }, events: [] };
}

// Loot tables — SPEC F09 / Assumptions 3, 6, 15.
// Every kill drops coins 1 + floor(index/3); 25% chance of exactly one
// weighted trinket. Randomness comes ONLY from the injected Rng.

import type { Rng } from './rng.js';
import type { ItemDef, ItemDrop } from './types.js';

/** The always-dropped currency item. */
export const COIN_ITEM: ItemDef = { id: 'coin', name: 'Coin', kind: 'coin' };

/** Chance that a kill also drops one trinket (SPEC Assumption 3). */
export const TRINKET_CHANCE = 0.25;

export interface WeightedTrinket {
  readonly item: ItemDef;
  readonly weight: number;
}

/** Weighted trinket table (SPEC F09). Never reorder — weights are frozen. */
export const TRINKET_TABLE: readonly WeightedTrinket[] = [
  { item: { id: 'sword_shard', name: 'Sword Shard', kind: 'trinket' }, weight: 5 },
  { item: { id: 'slime_gel', name: 'Slime Gel', kind: 'trinket' }, weight: 4 },
  { item: { id: 'bone', name: 'Bone', kind: 'trinket' }, weight: 3 },
  { item: { id: 'gem', name: 'Gem', kind: 'trinket' }, weight: 2 },
  { item: { id: 'crown', name: 'Crown', kind: 'trinket' }, weight: 1 },
];

const TOTAL_WEIGHT = TRINKET_TABLE.reduce((sum, t) => sum + t.weight, 0);

/** Coins dropped by the monster at `index`: 1 + floor(index/3), clamped total. */
export function coinsForIndex(index: number): number {
  return 1 + Math.floor(Math.max(0, Math.floor(index)) / 3);
}

function pickWeightedTrinket(rng: Rng): ItemDef {
  let r = rng.next() * TOTAL_WEIGHT;
  for (const entry of TRINKET_TABLE) {
    r -= entry.weight;
    if (r < 0) {
      return entry.item;
    }
  }
  // Unreachable while rng.next() < 1; keeps the function total anyway.
  return COIN_ITEM;
}

/**
 * Roll the drops for killing the monster at 0-based global `monsterIndex`:
 * always exactly one coin drop of amount 1 + floor(index/3) (first element),
 * plus a TRINKET_CHANCE chance of exactly one weighted trinket (amount 1).
 * Consumes 1 rng draw normally, 2 when a trinket drops.
 */
export function rollLoot(rng: Rng, monsterIndex: number): ItemDrop[] {
  const drops: ItemDrop[] = [{ item: COIN_ITEM, amount: coinsForIndex(monsterIndex) }];
  if (rng.next() < TRINKET_CHANCE) {
    drops.push({ item: pickWeightedTrinket(rng), amount: 1 });
  }
  return drops;
}

// Hero collection and repeat mastery. The engine supplies RNG, time and history.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';
import { RARE_HERO_FORMS, requirementsMet } from './discovery.js';
import type { DiscoveryContext, Requirement } from './discovery.js';
import { discoveryContext } from './progress.js';
import { PROGRESSION_PARAMETERS as progression } from './progression.js';

export interface HeroRoll { formId: string; buffPercent: number; stacks?: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
  rarity: 'standard' | 'rare';
  description: string;
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
  /** Requirement when this offer opened; preserves one pending v0.4 offer. */
  offerLevel?: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['검사', 'fire'], ['창술사', 'water'], ['거너', 'wind'],
  ['성직자', 'earth'], ['도적', 'dark'], ['광전사', 'fire'],
  ['마법사', 'water'], ['격투가', 'wind'], ['수호기사', 'earth'],
  ['소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const STANDARD_HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
    rarity: 'standard' as const,
    description: `${RANKS[Math.floor(i / 10)]}의 길을 걷는 ${archetype[0]}. ${i % 10 < 5 ? '같은 속성의 동료' : '모든 동료'}에게 힘을 보탠다.`,
  });
}));
export const HERO_FORMS: readonly HeroForm[] = Object.freeze([...STANDARD_HERO_FORMS, ...RARE_HERO_FORMS]);
export const HERO_MIN_LEVEL = progression.heroMinLevel;
export const HERO_MAX_REINCARNATIONS = 1_000_000;
export const HERO_DEFER_MS = progression.heroDeferMs;
export const HERO_REST_MS = progression.heroRestMs;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
const heroFormsById = new Map(HERO_FORMS.map((form) => [form.id, form]));
export const heroForm = (id: string): HeroForm | undefined => heroFormsById.get(id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
const count = (value: number, max: number): number =>
  Number.isFinite(value) ? Math.max(0, Math.min(max, Math.floor(value))) : 0;
export const heroRequiredLevel = (reincarnations: number): number =>
  HERO_MIN_LEVEL + Math.min(progression.heroLevelStepCap,
    Math.floor((count(reincarnations, HERO_MAX_REINCARNATIONS) + 1) / progression.heroLevelStepEvery));
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * count(reincarnations, 100);
/** A pending promise survives later tuning, including a prior v0.7 level 26 offer. */
const pendingOfferLevel = (value: unknown): number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 12 ? value : 12;
export interface HeroReadiness {
  status: 'capped' | 'rest' | 'defer' | 'level' | 'ready';
  requiredLevel: number;
  remainingMs: number;
}
/** One action gate for the engine and both displays, including legacy offers. */
export const heroReadiness = (level: number, hero?: HeroProgress): HeroReadiness => {
  const requiredLevel = hero?.choices.length === 3
    ? pendingOfferLevel(hero.offerLevel)
    : heroRequiredLevel(hero?.reincarnations ?? 0);
  const rest = hero?.restRemainingMs ?? 0;
  const defer = hero?.deferRemainingMs ?? 0;
  const status = (hero?.reincarnations ?? 0) >= HERO_MAX_REINCARNATIONS ? 'capped'
    : rest > 0 ? 'rest' : defer > 0 ? 'defer' : level >= requiredLevel ? 'ready' : 'level';
  return { status, requiredLevel, remainingMs: status === 'rest' ? rest : status === 'defer' ? defer : 0 };
};
export const heroReady = (level: number, hero?: HeroProgress): boolean => heroReadiness(level, hero).status === 'ready';
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

const unlockedHeroRank = (reincarnations: number): number => Math.min(5, reincarnations + 1);
const eligibleHeroForms = (hero: HeroProgress, context?: DiscoveryContext): readonly HeroForm[] => [
  ...STANDARD_HERO_FORMS.filter((form) => form.rank <= unlockedHeroRank(hero.reincarnations)),
  ...RARE_HERO_FORMS.filter((form) => requirementsMet(form.requirements, context)),
];
/** Eligibility is the offer pool, independent of the menu/level/rest action gate. */
export const eligibleHeroIds = (state: Pick<GameState, 'hero' | 'progress' | 'killCount'>): string[] =>
  eligibleHeroForms(state.hero ?? newHeroProgress(),
    discoveryContext(state, heroForm(state.hero?.equipped.formId ?? '')?.type)).map((form) => form.id);

/** Only already-open v0.6 promises may use these three original recipes. */
